class Solution {
public:
    long long smallestNumber(long long num) {
        if(num==0) return 0;
        bool neg=num<0;long long x=neg?-num:num;
        string s=to_string(x);
        if(neg) sort(s.rbegin(),s.rend());
        else {sort(s.begin(),s.end());int i=0;while(s[i]=='0')++i;swap(s[0],s[i]);}
        return (neg?-1LL:1LL)*stoll(s);
    }
};
